// Replicates src/lib/requirements.js computeReqMatch + builds the WhatsApp
// template variables. Keep the MANDATORY_SHIFTS list IDENTICAL to the app.
const d = $json;
const MAND = [
  { key: 'weekend',       label: 'סופי שבוע',  emoji: '🎉' },
  { key: 'nights',        label: 'לילות',      emoji: '🌙' },
  { key: 'holidays',      label: 'חגים',       emoji: '📅' },
  { key: 'early_morning', label: 'בוקר מוקדם', emoji: '🌅' }
];
const mand = Array.isArray(d.mandatory_shifts) ? d.mandatory_shifts : [];
const answers = d.answers || {};
const list = MAND.filter(s => mand.includes(s.key)).map(s => ({ ...s, answerKey: 'req_' + s.key }));

// commitment requirement
const cmin = d.commit_min, cmax = d.commit_max;
if (cmin != null || cmax != null) {
  let lbl = '';
  if (cmin != null && cmax != null) lbl = cmin >= 5 ? '5+ משמרות בשבוע' : (cmin === cmax ? cmin + ' משמרות בשבוע' : cmin + '–' + cmax + ' משמרות בשבוע');
  else if (cmin != null) lbl = 'לפחות ' + cmin + ' משמרות בשבוע';
  else lbl = 'עד ' + cmax + ' משמרות בשבוע';
  list.push({ key: 'commitment', label: lbl, emoji: '🗓️', answerKey: 'req_commitment' });
}

let met = 0; const lines = [];
for (const r of list) {
  const a = answers[r.answerKey];
  let dot, txt;
  if (a === undefined || a === null) { dot = '⚫'; txt = 'לא נשאל/ה'; }
  else if (a === true) { dot = '🟢'; txt = 'מוכן/ה'; met++; }
  else { dot = '🔴'; txt = 'לא מוכן/ה'; }
  lines.push(dot + ' ' + r.emoji + ' ' + r.label + ' — ' + txt);
}
const score = list.length ? Math.round((met / list.length) * 100) : null;

// (#4) normalize the restaurant's target number to E.164 for WhatsApp
function toE164(raw) {
  let x = String(raw || '').replace(/\D/g, '');
  if (!x) return null;
  if (x.startsWith('972')) return '+' + x;
  if (x.startsWith('0'))   x = x.slice(1);
  return '+972' + x;
}
const to = toE164(d.wa_target);

const expMap = { none: 'ללא ניסיון', '1_plus': 'שנה+', '2_plus': 'שנתיים+', '3_plus': '3 שנים+', '5_plus': '5 שנים+' };
const expTxt = expMap[d.cand_experience] || d.cand_experience || '';
const candLine = (d.cand_name || 'מועמד/ת') + (d.cand_city ? ' · ' + d.cand_city : '');
const metaLine = [expTxt ? '💼 ' + expTxt : null, d.cand_min_rate ? '💰 ₪' + d.cand_min_rate + '/שעה' : null].filter(Boolean).join('   ');

return {
  application_id: d.application_id,
  to_whatsapp: to,
  restaurant_name: d.restaurant_name,
  cand_line: candLine,
  meta_line: metaLine || '—',
  score_txt: score != null ? score + '%' : '—',
  reqs_block: lines.join('\n') || 'אין דרישות מוגדרות',
  accept_payload: 'accept:' + d.application_id,
  reject_payload: 'reject:' + d.application_id
};
